import{_ as a,o as n,c as e,a5 as t}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"Android keystore 密码与 APK 签名：打包时发生什么、安装时验什么","description":"正式 keystore 的 store 密码与 key 密码、Debug 默认证书、空密码风险，以及 APK 签名块、验签两步（双 hash 对比）与安装流程。","frontmatter":{"title":"Android keystore 密码与 APK 签名：打包时发生什么、安装时验什么","date":"2026-05-19T00:00:00.000Z","tags":["uni-app","Android","keystore","APK 签名","Gradle"],"categories":["移动开发"],"description":"正式 keystore 的 store 密码与 key 密码、Debug 默认证书、空密码风险，以及 APK 签名块、验签两步（双 hash 对比）与安装流程。"},"headers":[],"relativePath":"posts/移动开发/uni-app/Android keystore 密码与 APK 签名：打包时发生什么、安装时验什么.md","filePath":"posts/移动开发/uni-app/Android keystore 密码与 APK 签名：打包时发生什么、安装时验什么.md","lastUpdated":1790163617000}'),p={name:"posts/移动开发/uni-app/Android keystore 密码与 APK 签名：打包时发生什么、安装时验什么.md"};function o(l,s,r,d,i,h){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="android-keystore-密码与-apk-签名" tabindex="-1">Android keystore 密码与 APK 签名 <a class="header-anchor" href="#android-keystore-密码与-apk-签名" aria-label="Permalink to &quot;Android keystore 密码与 APK 签名&quot;">​</a></h1><p>本文是 uni-app Android 离线打包系列的补充。完整三平台流程见 <a href="/blog/posts/移动开发/uni-app/移动端打包签名与 DCloud 离线打包教程">移动端打包签名与 DCloud 离线打包教程</a>。相关阅读：<a href="/blog/posts/移动开发/uni-app/Android uni-app 生产包需要什么？签名 SHA1、keystore 与构建流程">生产包需要什么</a>、<a href="/blog/posts/移动开发/uni-app/DCloud AppKey 是什么？离线打包三要素必须一致">DCloud AppKey 是什么</a>。</p><h2 id="keystore-的两个密码" tabindex="-1">keystore 的两个密码 <a class="header-anchor" href="#keystore-的两个密码" aria-label="Permalink to &quot;keystore 的两个密码&quot;">​</a></h2><p>正式包用的 keystore 生成时会有两个密码：<strong>keystore 密码</strong> 和 <strong>key 密码</strong>（可以设成一样）。你们项目里的 <code>RELEASE_STORE_PASSWORD</code>、<code>RELEASE_KEY_PASSWORD</code> 就是这两个。</p><table tabindex="0"><thead><tr><th>密码</th><th>作用</th></tr></thead><tbody><tr><td><code>RELEASE_STORE_PASSWORD</code></td><td>打开 keystore 文件（保险柜）</td></tr><tr><td><code>RELEASE_KEY_PASSWORD</code></td><td>使用 keystore 里某把 key 签名（盖章）</td></tr></tbody></table><p>容易觉得「不用设」的是 <strong>Debug 包</strong>：Android Studio 自动用 <code>debug.keystore</code>，默认密码是 <code>android</code>，不是自己新生成时填的。</p><h3 id="和-ssh-openssl-的区别" tabindex="-1">和 SSH / OpenSSL 的区别 <a class="header-anchor" href="#和-ssh-openssl-的区别" aria-label="Permalink to &quot;和 SSH / OpenSSL 的区别&quot;">​</a></h3><p>你说的「一路回车」多半是 <strong>SSH 密钥</strong>（<code>ssh-keygen</code>）或 <strong>OpenSSL</strong>，passphrase 可以留空。</p><p><strong>Android 正式签名 keystore 不一样</strong>：<code>keytool</code> 生成时也会问密码，理论上也能全回车留空，但：</p><ol><li>你们项目里 <strong>已经设了密码</strong>（<code>secrets.properties</code> 里的 <code>RELEASE_STORE_PASSWORD</code> / <code>RELEASE_KEY_PASSWORD</code>）</li><li>Release 打包 <strong>Gradle 会检查密码非空</strong>，空的话 <code>assembleRelease</code> 直接失败</li></ol><p>所以日常开发 Debug 用默认 <code>debug.keystore</code>（密码 <code>android</code>）可以不管；<strong>你们这个项目的生产包 keystore 是有密码的，不能当 SSH 那样全回车。</strong></p><h2 id="去掉-gradle-检查-空密码能打包吗" tabindex="-1">去掉 Gradle 检查，空密码能打包吗？ <a class="header-anchor" href="#去掉-gradle-检查-空密码能打包吗" aria-label="Permalink to &quot;去掉 Gradle 检查，空密码能打包吗？&quot;">​</a></h2><p><strong>可以，但有个前提。</strong></p><p>去掉 <code>build.gradle</code> 里那段检查之后：</p><ul><li><strong>keystore 当初就是一路回车、没设密码生成的</strong> → 两个密码都留空，Gradle 签名 <strong>一般能过</strong>，Release 也能打出来。</li><li><strong>keystore 当初设过密码</strong>（你们仓库里现在是这种）→ 去掉检查也 <strong>不行</strong>，会在真正签名那步报错，不是 Gradle 检查拦的。</li></ul><p>所以：<strong>空密码能不能用，取决于 keystore 文件本身有没有密码</strong>，不是 Gradle 检查决定的。你们现在的 keystore 是有密码的，不能填空。</p><h2 id="不设密码有什么风险" tabindex="-1">不设密码有什么风险？ <a class="header-anchor" href="#不设密码有什么风险" aria-label="Permalink to &quot;不设密码有什么风险？&quot;">​</a></h2><p><strong>主要风险就一个：谁拿到 <code>.keystore</code> 文件，谁就能用你的身份签名发 APK。</strong></p><p>不设密码时：</p><ul><li>不需要再破解，文件拷走就能签正式包</li><li>备份、U 盘、误传 Git、电脑被入侵，后果一样</li><li>别人可以冒名更新你的 App（包名相同 + 同一证书 = 能覆盖安装）</li></ul><p>设密码后：</p><ul><li>光有文件还不够，还要知道密码才能签</li><li>但密码也存在仓库里的话，保护会打折扣（你们现在是 <strong>keystore + 密码都在 <code>.secrets/</code></strong>）</li></ul><p><strong>和 DCloud AppKey、SHA1 无关</strong>——不设密码不改变指纹，只让 keystore <strong>更容易被盗用</strong>。</p><p><strong>结论</strong>：正式上架用的 keystore <strong>建议设密码</strong>；Debug 的 <code>debug.keystore</code> 不设无所谓。</p><h2 id="打包时-apk-里多了什么" tabindex="-1">打包时 APK 里多了什么 <a class="header-anchor" href="#打包时-apk-里多了什么" aria-label="Permalink to &quot;打包时 APK 里多了什么&quot;">​</a></h2><p>可以想成 <strong>两层东西</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>APK</span></span>
<span class="line"><span>├── 正常内容（代码、资源、assets、www…）</span></span>
<span class="line"><span>├── 签名块（私钥对「内容摘要」签出来的结果）</span></span>
<span class="line"><span>└── 证书（里面的公钥，用来验签）</span></span></code></pre></div><p>更细一点（v1 传统方式，概念最好懂）：</p><ol><li>先把 APK 里每个文件算 hash，写进 <code>META-INF/MANIFEST.MF</code></li><li>用 <strong>私钥</strong> 对这些 hash 再签一次 → 得到 <code>META-INF/CERT.SF</code>、<code>META-INF/CERT.RSA</code>（或 <code>.DSA</code>）</li><li><code>CERT.RSA</code> 里 <strong>同时带着证书（公钥）和签名块</strong></li></ol><p>v2/v3 是把签名块放在 APK 末尾的 <strong>Signing Block</strong> 里，原理一样：<strong>私钥签内容摘要，证书（公钥）跟着 APK 走</strong>。</p><h2 id="安装时系统干什么" tabindex="-1">安装时系统干什么 <a class="header-anchor" href="#安装时系统干什么" aria-label="Permalink to &quot;安装时系统干什么&quot;">​</a></h2><p><strong>会检查。</strong> 大致流程：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户点安装</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>PackageManager 读 APK</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>① 取出证书（公钥）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>② 用公钥验证签名块</span></span>
<span class="line"><span>   → 内容摘要和签名对不上 = 被改过 → 安装失败</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>③ 若是更新安装</span></span>
<span class="line"><span>   → 对比已装 App 的证书</span></span>
<span class="line"><span>   → 必须同一张证（同一开发者）</span></span>
<span class="line"><span>   → 否则拒绝覆盖（防别人冒名更新）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>④ 通过 → 写入 /data/app，显示安装成功</span></span></code></pre></div><p><strong>② 怎么验</strong>：不是公钥和签名块直接比，详见下节「验签拆成两步」——用公钥从签名块还原 hash，再和重算内容的 hash 对比。</p><p><strong>③ 更新规则</strong>：<code>com.future.hyqhjskh</code> 已装过，新包必须是 <strong>同一 keystore 签的</strong> 才能覆盖；换证书 = 不同 App，只能卸了重装。</p><h2 id="验签拆成两步-比的是两个-hash" tabindex="-1">验签拆成两步：比的是两个 hash <a class="header-anchor" href="#验签拆成两步-比的是两个-hash" aria-label="Permalink to &quot;验签拆成两步：比的是两个 hash&quot;">​</a></h2><p>把「验签」拆成两步就清楚了：<strong>不是公钥和签名块比大小，而是用公钥从签名块里还原出一个 hash，再和现算的 hash 比。</strong></p><h3 id="打包时-私钥做的事" tabindex="-1">打包时（私钥做的事） <a class="header-anchor" href="#打包时-私钥做的事" aria-label="Permalink to &quot;打包时（私钥做的事）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 把整个 APK 内容（除签名区外）算一遍 hash</span></span>
<span class="line"><span>   → 得到一串固定长度的摘要，例如：A7F3B2...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 用私钥对「这个 hash」做数学运算</span></span>
<span class="line"><span>   → 得到签名块（一长串二进制）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 签名块 + 证书（公钥）一起塞进 APK</span></span></code></pre></div><p>重点：<strong>私钥签的不是整个 APK 文件本身，而是「内容的 hash」。</strong></p><h3 id="安装时-系统做的事" tabindex="-1">安装时（系统做的事） <a class="header-anchor" href="#安装时-系统做的事" aria-label="Permalink to &quot;安装时（系统做的事）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 同样规则，把当前 APK 内容再算一遍 hash</span></span>
<span class="line"><span>   → 得到：A7F3B2...  （或如果被改过 → X9K1...）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 用证书里的公钥，对「签名块」做逆运算</span></span>
<span class="line"><span>   → 还原出当初签进去的那个 hash</span></span>
<span class="line"><span>   → 应该也是：A7F3B2...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 对比：</span></span>
<span class="line"><span>   现算的 hash  ==  公钥还原出来的 hash ？</span></span>
<span class="line"><span>        是 → 验签通过，内容没被改</span></span>
<span class="line"><span>        否 → 验签失败，拒绝安装</span></span></code></pre></div><h3 id="「一验证得到了什么-和什么比-」" tabindex="-1">「一验证得到了什么？和什么比？」 <a class="header-anchor" href="#「一验证得到了什么-和什么比-」" aria-label="Permalink to &quot;「一验证得到了什么？和什么比？」&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>得到什么</th><th>和什么比</th></tr></thead><tbody><tr><td>公钥 + 签名块</td><td>还原出 <strong>当初签名时的 hash</strong></td><td>—</td></tr><tr><td>重算 APK 内容</td><td><strong>现在的 hash</strong></td><td>和上面那个比</td></tr></tbody></table><p><strong>比的是两个 hash 是否相同</strong>，不是公钥和签名块直接比。</p><h3 id="为什么改一个文件就失败" tabindex="-1">为什么改一个文件就失败 <a class="header-anchor" href="#为什么改一个文件就失败" aria-label="Permalink to &quot;为什么改一个文件就失败&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原包：内容 → hash = A7F3B2 → 私钥签进签名块</span></span>
<span class="line"><span>改包：内容&#39; → hash = X9K1... （变了）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>验签：公钥还原出来还是 A7F3B2</span></span>
<span class="line"><span>      现算出来是 X9K1...</span></span>
<span class="line"><span>      A7F3B2 ≠ X9K1...  → 失败</span></span></code></pre></div><h3 id="为啥必须用配对的公钥" tabindex="-1">为啥必须用配对的公钥 <a class="header-anchor" href="#为啥必须用配对的公钥" aria-label="Permalink to &quot;为啥必须用配对的公钥&quot;">​</a></h3><p>签名块是 <strong>私钥对 hash 加密/签名</strong> 的结果。<br> 只有 <strong>配对的公钥</strong> 能正确还原出那个 hash；换别的公钥，还原出来是乱码，对不上。</p><p>所以：<strong>不是验证「公钥和签名块匹不匹配」，而是验证「签名块能不能证明内容 hash 没被改」。</strong></p><h3 id="验签一句话" tabindex="-1">验签一句话 <a class="header-anchor" href="#验签一句话" aria-label="Permalink to &quot;验签一句话&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>公钥 + 签名块  →  还原出「当初签名的 hash」</span></span>
<span class="line"><span>重算 APK 内容  →  得到「现在的 hash」</span></span>
<span class="line"><span>两个 hash 一样  →  通过；不一样  →  被改过或签名伪造</span></span></code></pre></div><h2 id="和-dcloud-的关系" tabindex="-1">和 DCloud 的关系 <a class="header-anchor" href="#和-dcloud-的关系" aria-label="Permalink to &quot;和 DCloud 的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>谁</th><th>查什么</th></tr></thead><tbody><tr><td><strong>Android 系统</strong></td><td>签名块 + 证书 → APK 有没有被改、更新是不是同开发者</td></tr><tr><td><strong>DCloud SDK</strong></td><td>证书 SHA1 + 包名 + appid + AppKey → 离线包授权</td></tr></tbody></table><p>系统 <strong>不管</strong> DCloud AppKey；DCloud <strong>不管</strong> Google Play。各验各的。</p><h2 id="一句话串起来" tabindex="-1">一句话串起来 <a class="header-anchor" href="#一句话串起来" aria-label="Permalink to &quot;一句话串起来&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>打包：内容 → hash → 私钥签进签名块；证书（公钥）也进 APK</span></span>
<span class="line"><span>安装：公钥还原 hash，重算内容 hash，两个 hash 一致才通过；更新还要证书一致</span></span></code></pre></div><hr><p><strong>系列导航</strong></p><ul><li><a href="/blog/posts/移动开发/uni-app/移动端打包签名与 DCloud 离线打包教程">移动端打包签名与 DCloud 离线打包教程（总览）</a></li><li><a href="/blog/posts/移动开发/uni-app/DCloud AppKey 是什么？离线打包三要素必须一致">DCloud AppKey 是什么？</a></li><li><a href="/blog/posts/移动开发/uni-app/Android uni-app 生产包需要什么？签名 SHA1、keystore 与构建流程">Android uni-app 生产包需要什么？</a></li><li><a href="/blog/posts/移动开发/uni-app/SHA1 是什么？Android、iOS 与鸿蒙签名发证有何不同">SHA1 是什么？Android、iOS 与鸿蒙签名发证有何不同</a></li></ul>`,60)])])}const u=a(p,[["render",o]]);export{g as __pageData,u as default};
